1	import { spawn, ChildProcess } from "node:child_process";
2	import * as path from "node:path";
3	import * as fs from "node:fs";
4	import * as os from "node:os";
5	import { pathToFileURL, fileURLToPath } from "node:url";
6	import { buildMcpEnvironment } from "./mcp.js";
7	import { MAX_DIAGNOSTIC_MESSAGE, MAX_DIAGNOSTIC_RECORDS, UNTRUSTED_FENCE_END, UNTRUSTED_FENCE_START, fenceUntrusted, sanitizeDiagnosticMessage } from "./diagnostics.js";
8	import { MAX_SNAPSHOT_BYTES } from "./file_diff.js";
9	import { redactPlain } from "./protocol.js";
10	
11	const LSP_TOOLCHAIN_VARS = ["RUSTUP_HOME", "CARGO_HOME", "RUSTUP_TOOLCHAIN", "GOPATH", "GOROOT", "GOCACHE", "GOMODCACHE"];
12	/**
13	 * Documents one server keeps open; the least recently queried one beyond this is closed (`didClose`), which hands that
14	 * file back to the server's own reading of the disk. Every query re-checks every open document (one realpath and one
15	 * stat each), and a server re-analyses its open documents on each change, so the set is kept to what an agent works on
16	 * at one time (an editor's worth of tabs), not every file it ever asked about.
17	 */
18	export const MAX_OPEN_DOCUMENTS = 32;
19	/**
20	 * A file's stat is taken as proof that it has not changed only when its newest timestamp was at least this old when the
21	 * file was read. Timestamps come from a clock that advances in steps (a kernel tick, or 1 to 2 s on coarse file systems):
22	 * a second write inside the step of the first leaves them equal, so a file changed that recently is compared by content.
23	 */
24	export const STAT_SETTLE_MS = 2_000;
25	/**
26	 * Push-only servers: how long the server must have published nothing before a list that predates a change to another
27	 * document is taken as still standing (see `settledAt`). It has to outlast the gap between a server's publish for the
28	 * changed file and its publish for a dependent one; servers batch or debounce those within a few hundred milliseconds,
29	 * and 1 s is several times that. Longer would make every such query slower by as much; shorter would return more old
30	 * lists from a server that is slow to reach the dependent file. Counted from the last publish, so a query made a moment
31	 * after an edit usually finds most of it already spent.
32	 */
33	export const PUBLISH_QUIET_MS = 1_000;
34	
35	// ----------------------------------------------------------------------------------------------------------- bounds
36	// What the client reads, keeps and hands on, each with a named limit. Everything a server sends is untrusted in size too.
37	
38	/**
39	 * A file larger than this is not given to a language server: it is refused before it is read, and closed if it grows
40	 * past this while open. The number is the one Nexus already uses for "too large to show a change line by line"
41	 * (file_diff.ts MAX_SNAPSHOT_BYTES, 2 MiB; the verification snapshot uses the same): a query here is about a line and a
42	 * column, and a file the edit path no longer handles by line is outside that. The cost side: this client syncs full
43	 * text, so every change to an open file sends the whole file again, and the client keeps one copy of each open file.
44	 */
45	export const LSP_MAX_FILE_BYTES = MAX_SNAPSHOT_BYTES;
46	/**
47	 * One message from a server (its Content-Length). A larger one is not buffered: the server is stopped and reported as
48	 * failed with that cause. 16 MiB is the limit this client has had since it was written (pinned by lsp_trust.test.ts:
49	 * a message just under it is accepted); answers to the three queries made here are kilobytes.
50	 */
51	export const LSP_MAX_MESSAGE_BYTES = 16 * 1024 * 1024;
52	/** The header block of one message; the protocol's two headers are under 100 bytes. Bytes that never form a header are not collected past this. */
53	const LSP_MAX_HEADER_BYTES = 8 * 1024;
54	/**
55	 * Diagnostics kept per list: what the tool shows (diagnostics.ts MAX_DIAGNOSTIC_RECORDS), so the output never cuts a
56	 * second time and the count of what was left out is the client's. When a list is longer the most severe are kept.
57	 */
58	export const LSP_MAX_DIAGNOSTICS = MAX_DIAGNOSTIC_RECORDS;
59	/** Characters kept of one diagnostic's message (the tool shows MAX_DIAGNOSTIC_MESSAGE after cleaning, which can only shorten), and of its source and code. */
60	const LSP_MAX_DIAGNOSTIC_TEXT = 2 * MAX_DIAGNOSTIC_MESSAGE;
61	const LSP_MAX_LABEL = 200;
62	/** A pull report's `resultId` longer than this is not kept: the next request then asks for a full report. */
63	const LSP_MAX_RESULT_ID = 1024;
64	/** Definition targets returned by one query; the rest are counted. One is usual, a handful for overloads and merged declarations. A judgement. */
65	export const LSP_MAX_DEFINITION_TARGETS = 20;
66	/** Characters of hover text returned (a quarter of the 32,000 a diagnostics block may take); the rest is cut with a note. A judgement. */
67	export const LSP_MAX_HOVER_CHARS = 8_000;
68	/** Progress tokens tracked at once, capabilities a server may have registered, and `window/showMessage` / `logMessage` lines kept for `status()`. */
69	const LSP_MAX_PROGRESS_TOKENS = 256;
70	const LSP_MAX_REGISTRATIONS = 256;
71	const LSP_SERVER_MESSAGE_RING = 20;
72	
73	/** Limits a test may lower; the product runs with LSP_LIMITS. */
74	export interface LspLimits {
75	  fileBytes: number;
76	  messageBytes: number;
77	}
78	export const LSP_LIMITS: Readonly<LspLimits> = Object.freeze({ fileBytes: LSP_MAX_FILE_BYTES, messageBytes: LSP_MAX_MESSAGE_BYTES });
79	
80	/*
81	 * WORST-CASE MEMORY one client retains between queries (bytes; a JavaScript string costs up to 2 bytes per character):
82	 *
83	 *   MAX_OPEN_DOCUMENTS x ( 2 x fileBytes                                               text of one open document
84	 *                        + 2 x LSP_MAX_DIAGNOSTICS x 2 x (LSP_MAX_DIAGNOSTIC_TEXT + 2 x LSP_MAX_LABEL)
85	 *                                                                                      its pushed and its pulled list
86	 *                        + 2 x LSP_MAX_RESULT_ID )
87	 *   + messageBytes + LSP_MAX_HEADER_BYTES + one stdout chunk (64 KiB)                  the parse buffer
88	 *   + STDERR_RING_BYTES
89	 *   + LSP_MAX_PROGRESS_TOKENS x 2 x LSP_MAX_LABEL + LSP_MAX_REGISTRATIONS x 4 x LSP_MAX_LABEL
90	 *   + LSP_SERVER_MESSAGE_RING x 2 x (MAX_DIAGNOSTIC_MESSAGE + 60)
91	 *
92	 * With the product's values: 32 x (4 MiB + 280 KB + 2 KB) + 16 MiB + ... = about 153 MiB, of which 128 MiB is the text
93	 * of 32 files that are each at the size limit and not ASCII. Nothing is kept per query: a request and a waiter live
94	 * as long as the call that made them. Closing a document (eviction, deletion, growth past the limit) drops all of the
95	 * first term for it: `documents` and `opened` are the only references to an OpenDocument.
96	 */
97	
98	// ---------------------------------------------------------------------------------------------------------- timings
99	// One value per phase, each tied to what was measured (docs/LSP_REAL_SERVERS.md) or marked as a judgement. A server's
100	// spec can override any of them (`LspServerSpec.timings`), and a manager option overrides both (tests pass small values).
101	
102	/**
103	 * Start: how long `initialize` may take. All four real servers answered inside the former 5 s limit on the hosted runs
104	 * (44606102675, 44670790609); a server that is missing or exits is reported at once and no longer waits for this, so the
105	 * limit only costs when a process hangs. Twice the proven value, for a loaded machine. A judgement, not a measurement.
106	 */
107	export const LSP_START_TIMEOUT_MS = 10_000;
108	/**
109	 * A query on a server that is ready: the value the tools always used. Also how long a call waits, at the least, on a
110	 * server that is not ready, and the timeout of one hover or definition request.
111	 */
112	export const LSP_WARM_QUERY_TIMEOUT_MS = 5_000;
113	/**
114	 * Cold start: how long after `initialize` a call may wait for the server's first analysis, and how long a server that
115	 * reports no progress is taken to be warming up. The default adds nothing to the warm timeout: no first-query time is
116	 * recorded for typescript-language-server, pyright or gopls (the real-server suite passes 60 to 90 s and does not record
117	 * what was used), so nothing longer is justified yet.
118	 */
119	export const LSP_COLD_START_ALLOWANCE_MS = LSP_WARM_QUERY_TIMEOUT_MS;
120	/**
121	 * rust-analyzer: a first diagnostics call on a tiny crate took about 13 s locally and about 18 s on a hosted runner;
122	 * 25 s covers the slower one with 40% to spare.
123	 *
124	 * THE COLD-START DECISION: a bounded longer first wait, not "unavailable, try again" after the warm timeout. With the
125	 * measured 13 to 18 s, the warm timeout would end three or four calls in a row as "still indexing", each a model round
126	 * trip that costs more than the seconds it saves, where one call that waits returns the real answer. The wait is bounded
127	 * and is counted from the server's start, not from the call: a call made while the server is still indexing waits for
128	 * what is left of the allowance (at least the warm timeout), so a second call never starts the allowance over, and one
129	 * made after it has run out reports the state, with the time indexing has taken, after the warm timeout. A project that
130	 * needs longer keeps indexing between calls; `LspBridgeManager.warmUp` starts that before the first query.
131	 */
132	export const RUST_ANALYZER_COLD_START_ALLOWANCE_MS = 25_000;
133	/** A server's progress must have been over for this long before it counts as ready and its lists as final (rust-analyzer runs its phases back to back; passed on the real server since CS-6). */
134	export const LSP_PROGRESS_QUIET_MS = 1_500;
135	/**
136	 * Staged servers, after an edit: when no progress cycle begins after the change (no check on save), a list for the new
137	 * version is taken as final this long after the change. 8 s is the window the real rust-analyzer case needed: it
138	 * reproduced a version-matched list that still carried the previous `rustc` result right after an edit. A cycle that
139	 * began after the change and ended is the usual evidence, and does not wait for this.
140	 */
141	export const LSP_EDIT_SETTLE_MS = 8_000;
142	/** Hover and definition on a server that is not ready: the first pause before asking again; it doubles up to the cap. A judgement. */
143	export const LSP_READINESS_RETRY_MS = 250;
144	const READINESS_RETRY_CAP_MS = 2_000;
145	/**
146	 * A failed start (not installed, exited, no answer to initialize) is answered from memory for this long, then tried
147	 * again; a changed PATH ends it at once, so installing the server mid-session works. Long enough that a model asking
148	 * again does not spawn a process per call, short enough to notice an install. A judgement.
149	 */
150	export const LSP_START_FAILURE_RECHECK_MS = 30_000;
151	/** A crashed server is started again by the next query, but not sooner than this after the crash; doubled per crash. A judgement. */
152	export const LSP_RESTART_BACKOFF_MS = 1_000;
153	/** Restarts after a crash, per session and server; one more crash and it stays down until PATH changes or Nexus restarts. A judgement. */
154	export const LSP_MAX_RESTARTS = 3;
155	/**
156	 * Stopping a server, in order: the `shutdown` request (wait for its reply), the `exit` notification (wait for the
157	 * process to end), SIGTERM to its process group (wait), SIGKILL to the group (wait for the kernel to report the exit).
158	 * No measurement of real servers exists for these (docs/LSP_REAL_SERVERS.md records none), so each is a judgement:
159	 * an orderly server answers `shutdown` and exits within milliseconds; the first two together give a server that
160	 * writes an index on the way out (jdtls, rust-analyzer) 3 s to do it; SIGTERM gets as long as the request did. A
161	 * server that ignores everything is gone 5 s after the call, plus at most the last wait, which only bounds how long an
162	 * unkillable process is waited for. A server that had not answered `initialize` holds nothing to save and is killed at once.
163	 */
164	export const LSP_SHUTDOWN_REPLY_MS = 2_000;
165	export const LSP_EXIT_GRACE_MS = 1_000;
166	export const LSP_TERM_GRACE_MS = 2_000;
167	export const LSP_KILL_GRACE_MS = 1_000;
168	
169	export interface LspTimings {
170	  startMs: number;
171	  queryMs: number;
172	  coldStartMs: number;
173	  quietMs: number;
174	  editSettleMs: number;
175	  retryMs: number;
176	  startRecheckMs: number;
177	  restartBackoffMs: number;
178	  maxRestarts: number;
179	  shutdownReplyMs: number;
180	  exitGraceMs: number;
181	  termGraceMs: number;
182	  killGraceMs: number;
183	}
184	
185	export const LSP_TIMINGS: Readonly<LspTimings> = Object.freeze({
186	  startMs: LSP_START_TIMEOUT_MS,
187	  queryMs: LSP_WARM_QUERY_TIMEOUT_MS,
188	  coldStartMs: LSP_COLD_START_ALLOWANCE_MS,
189	  quietMs: LSP_PROGRESS_QUIET_MS,
190	  editSettleMs: LSP_EDIT_SETTLE_MS,
191	  retryMs: LSP_READINESS_RETRY_MS,
192	  startRecheckMs: LSP_START_FAILURE_RECHECK_MS,
193	  restartBackoffMs: LSP_RESTART_BACKOFF_MS,
194	  maxRestarts: LSP_MAX_RESTARTS,
195	  shutdownReplyMs: LSP_SHUTDOWN_REPLY_MS,
196	  exitGraceMs: LSP_EXIT_GRACE_MS,
197	  termGraceMs: LSP_TERM_GRACE_MS,
198	  killGraceMs: LSP_KILL_GRACE_MS,
199	});
200	
201	/** The last bytes of a server's stderr that are kept, and how much of them a failure report quotes. */
202	const STDERR_RING_BYTES = 4096;
203	const STDERR_TAIL_CHARS = 400;
204	/** After a server's exit, how long its stderr is given to deliver what it still holds (a child of the server can keep the pipe open). */
205	const STDERR_DRAIN_MS = 200;
206	
207	// ------------------------------------------------------------------------------------------------------------ state
208	
209	/**
210	 * Where one server is. `indexing`: it runs but has not finished analysing: work-done progress is in flight or ended
211	 * less than the quiet period ago, or, for a server that reports none, it started less than the cold-start allowance ago
212	 * and has answered nothing yet. A server marked `awaitProgress` is ready only after a progress cycle.
213	 */
214	export type LspServerState = "not_started" | "starting" | "initializing" | "indexing" | "ready" | "failed" | "stopped";
215	
216	export interface LspFailure {
217	  kind: "not_installed" | "spawn_failed" | "exited" | "initialize_timeout" | "crashed" | "crash_loop" | "message_too_large";
218	  /** One sentence, safe to show: it holds nothing the server wrote. */
219	  message: string;
220	  at: number;
221	  exitCode?: number | null;
222	  signal?: string | null;
223	  /** The end of the server's stderr: untrusted text, already capped, stripped of control characters and redacted. Show it fenced (`failureDetail`). */
224	  stderrTail?: string;
225	}
226	
227	export interface LspServerStatus {
228	  server: string;
229	  state: LspServerState;
230	  /** How long it has been in this state. */
231	  forMs: number;
232	  detail?: string;
233	  cause?: LspFailure;
234	  /** Crashes of this server in this session. */
235	  crashes?: number;
236	  /**
237	   * The server's latest `window/showMessage` and `window/logMessage` lines, oldest first: untrusted text, each cleaned as
238	   * a diagnostic message is (one line, capped, redacted). For an operator's view; show it to a model only inside the fence.
239	   */
240	  serverMessages?: string[];
241	}
242	
243	/** What a query returns in place of an answer when the server's state is the reason there is none. */
244	interface NoAnswer {
245	  reason: string;
246	  state?: LspServerStatus;
247	  /** Fenced untrusted text (the server's stderr) to show after the reason. */
248	  detail?: string;
249	}
250	
251	const seconds = (ms: number): string => (ms < 1000 ? `${Math.round(ms)} ms` : `${Math.round(ms / 100) / 10} s`);
252	
253	/** The stderr tail of a failure, fenced as untrusted, or undefined when there is none. */
254	export function failureDetail(cause: LspFailure | undefined): string | undefined {
255	  return cause?.stderrTail ? fenceUntrusted("language server stderr, last output", cause.stderrTail) : undefined;
256	}
257	
258	const noAnswer = (reason: string, state: LspServerStatus): NoAnswer => {
259	  const detail = failureDetail(state.cause);
260	  return { reason, state, ...(detail ? { detail } : {}) };
261	};
262	
263	/** `cmd` as the server's environment would find it, or null. A name is looked up on PATH; a path is taken as given, from `cwd`. */
264	function findCommand(cmd: string, pathVar: string, cwd: string): string | null {
265	  if (process.platform === "win32") return cmd; // extensions and App Paths decide there: left to the spawn, whose error is reported the same way
266	  const executable = (p: string): boolean => {
267	    try {
268	      fs.accessSync(p, fs.constants.X_OK);
269	      return fs.statSync(p).isFile();
270	    } catch {
271	      return false;
272	    }
273	  };
274	  if (cmd.includes("/") || cmd.includes(path.sep)) return executable(path.resolve(cwd, cmd)) ? cmd : null;
275	  for (const dir of pathVar.split(path.delimiter)) if (dir !== "" && executable(path.join(dir, cmd))) return path.join(dir, cmd);
276	  return null;
277	}
278	
279	const timedOut = (err: unknown): boolean => (err as any)?.code === "LSP_TIMEOUT";
280	const cancelled = (err: unknown): boolean => (err as any)?.code === "LSP_CANCELLED";
281	/** LSP `ServerCancelled`: the server abandoned a pull request; its data says whether to ask again. */
282	const SERVER_CANCELLED = -32802;
283	/** JSON-RPC: the answer to a server request this client does not implement, and to one it cannot take. */
284	const METHOD_NOT_FOUND = -32601;
285	const INVALID_PARAMS = -32602;
286	const APPLY_EDIT_REFUSAL = "This client does not let a language server edit files.";
287	/** How often one diagnostics query asks again after such a cancellation (within its timeout). */
288	const PULL_RETRIGGER_LIMIT = 3;
289	/** Wakes a query waiting for evidence that the server has settled: any publish, the end of a progress cycle, a close. */
290	const ANY_DOCUMENT = "";
291	
292	/**
293	 * `omitted`: how many more the server reported than `diagnostics` holds (LSP_MAX_DIAGNOSTICS; the most severe are kept).
294	 * `state` and `detail` are present only when the server's state is why there is no answer.
295	 */
296	export type DiagnosticsAnswer = { status: "ok"; diagnostics: LspDiagnostic[]; omitted?: number } | { status: "unavailable"; reason: string; state?: LspServerStatus; detail?: string };
297	
298	const SEVERITIES = ["error", "warning", "information", "hint"] as const;
299	/**
300	 * A diagnostic whose severity is missing (the protocol leaves that to the client) or is not 1 to 4 is reported as
301	 * this, one fixed value. "error" because the reader is an agent deciding whether its edit broke something: a server
302	 * that omits the severity of a real error must not have it read as a remark. (This client used to say "information".)
303	 */
304	export const LSP_DEFAULT_SEVERITY: LspDiagnostic["severity"] = "error";
305	
306	/** A protocol range with whole, non-negative numbers, or null when it is not one. */
307	function toRange(range: any): LspRange | null {
308	  const position = (p: any): LspPosition | null => (Number.isSafeInteger(p?.line) && p.line >= 0 && Number.isSafeInteger(p?.character) && p.character >= 0 ? { line: p.line, character: p.character } : null);
309	  const start = position(range?.start);
310	  const end = position(range?.end);
311	  return start && end ? { start, end } : null;
312	}
313	
314	const NO_RANGE: LspRange = { start: { line: 0, character: 0 }, end: { line: 0, character: 0 } };
315	
316	/** One list as it is kept: at most LSP_MAX_DIAGNOSTICS entries, each field bounded, and the count of what was left out. */
317	interface DiagnosticList {
318	  list: LspDiagnostic[];
319	  omitted: number;
320	}
321	
322	function toDiagnostics(items: any[]): DiagnosticList {
323	  const rank = (d: any): number => (d?.severity >= 1 && d?.severity <= 4 ? d.severity - 1 : SEVERITIES.indexOf(LSP_DEFAULT_SEVERITY));
324	  // Over the bound, the most severe are the ones kept (in the server's order among equals): the first fifty hints must not hide the error after them.
325	  const kept = items.length > LSP_MAX_DIAGNOSTICS ? [...items].sort((a, b) => rank(a) - rank(b)).slice(0, LSP_MAX_DIAGNOSTICS) : items;
326	  const list = kept.map((d: any): LspDiagnostic => ({
327	    range: toRange(d?.range) ?? NO_RANGE,
328	    severity: SEVERITIES[d?.severity - 1] ?? LSP_DEFAULT_SEVERITY,
329	    message: String(d?.message ?? "").slice(0, LSP_MAX_DIAGNOSTIC_TEXT),
330	    source: typeof d?.source === "string" ? d.source.slice(0, LSP_MAX_LABEL) : undefined,
331	    ...(typeof d?.code === "number" ? { code: d.code } : d?.code !== undefined && d?.code !== null ? { code: String(d.code).slice(0, LSP_MAX_LABEL) } : {}),
332	  }));
333	  return { list, omitted: items.length - list.length };
334	}
335	
336	const okAnswer = (d: DiagnosticList): DiagnosticsAnswer => ({ status: "ok", diagnostics: d.list, ...(d.omitted > 0 ? { omitted: d.omitted } : {}) });
337	
338	/** The text of a hover result in any of its forms (a string, a MarkedString, a list of those, MarkupContent); a code block keeps its language tag. */
339	function hoverContents(contents: unknown): string {
340	  const one = (c: any): string => {
341	    if (typeof c === "string") return c;
342	    if (typeof c?.value !== "string") return "";
343	    return typeof c.language === "string" && c.language !== "" ? `\`\`\`${c.language}\n${c.value}\n\`\`\`` : c.value;
344	  };
345	  return Array.isArray(contents) ? contents.map(one).filter((t) => t !== "").join("\n\n") : one(contents);
346	}
347	
348	/**
349	 * Hover text as it may be shown: it is written by whoever wrote the code under the cursor (doc comments), so it is
350	 * untrusted. Secrets redacted and terminal escapes removed (the helper the diagnostics path uses), control characters
351	 * removed (line breaks and tabs stay: it is prose and code), fence markers defused as in a diagnostic message, capped
352	 * with a note. The caller still puts it inside the untrusted-output fence.
353	 */
354	export function sanitizeHoverText(raw: string): string {
355	  // Cleaning can only shorten, so nothing past four times the cap can end up inside it: the rest is not worked on.
356	  const text = redactPlain(raw.slice(0, 4 * LSP_MAX_HOVER_CHARS))
357	    .replace(/\r\n?/g, "\n")
358	    .replace(/[\x00-\x08\x0b-\x1f\x7f-\x9f]+/g, " ")
359	    .split(UNTRUSTED_FENCE_START).join("(untrusted-tool-output")
360	    .split(UNTRUSTED_FENCE_END).join("(end-untrusted-tool-output)")
361	    .replace(/\n{3,}/g, "\n\n")
362	    .trim();
363	  if (text.length <= LSP_MAX_HOVER_CHARS && raw.length <= 4 * LSP_MAX_HOVER_CHARS) return text;
364	  return `${text.slice(0, LSP_MAX_HOVER_CHARS)}\n…[truncated: the hover text is ${raw.length} characters, the first ${Math.min(text.length, LSP_MAX_HOVER_CHARS)} are shown]`;
365	}
366	
367	/** A position argument as the tools take it: a whole number from 1 (a string of digits is read as that number), or null. */
368	function positiveInteger(value: unknown): number | null {
369	  const n = typeof value === "string" && /^[0-9]{1,10}$/.test(value) ? Number(value) : value;
370	  return typeof n === "number" && Number.isSafeInteger(n) && n >= 1 && n <= 0x7fffffff ? n : null;
371	}
372	
373	const POSITION_FORM = "line and character must be positive integers, counted from 1 (the first line is 1, the first character of a line is 1)";
374	const PATH_FORM = "path must be a non-empty string naming a file inside the workspace";
375	
376	const SYSTEM_BIN_DIRS = ["/usr/bin", "/bin", "/usr/local/bin", "/sbin", "/usr/sbin"];
377	
378	function realOrNull(p: string): string | null {
379	  try {
380	    return fs.realpathSync(p);
381	  } catch {
382	    return null;
383	  }
384	}
385	
386	/** The containment rule for documents; `child` and `root` are real paths. */
387	const outsideRoot = (root: string, child: string): boolean => {
388	  const rel = path.relative(root, child);
389	  return rel.startsWith("..") || path.isAbsolute(rel);
390	};
391	
392	const isInside = (parent: string, child: string): boolean => {
393	  const rel = path.relative(parent, child);
394	  return rel === "" || (rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel));
395	};
396	
397	/**
398	 * The environment a language server starts with: the MCP allowlist (no credentials) plus the toolchain locations the
399	 * servers need. PATH keeps only existing absolute entries that do not resolve (through symlinks) into the workspace, so
400	 * project content cannot supply the binary. When the workspace is a home directory or a system prefix that itself
401	 * contains the toolchain, its entries are kept: dropping them would leave no server installed.
402	 */
403	export function buildLspEnvironment(workspace: string, source: NodeJS.ProcessEnv = process.env): Record<string, string> {
404	  const env = buildMcpEnvironment();
405	  for (const k of LSP_TOOLCHAIN_VARS) if (source[k] !== undefined) env[k] = source[k]!;
406	  for (const [k, v] of Object.entries(env)) {
407	    if (/^(https?|all)_proxy$/i.test(k) && /\/\/[^/]*@/.test(v)) delete env[k];
408	  }
409	  const root = realOrNull(path.resolve(workspace));
410	  const broad =
411	    root !== null &&
412	    [os.homedir(), ...SYSTEM_BIN_DIRS].some((d) => {
413	      const real = realOrNull(d);
414	      return real !== null && isInside(root, real);
415	    });
416	  env.PATH = (env.PATH ?? "")
417	    .split(path.delimiter)
418	    .filter((d) => {
419	      if (!path.isAbsolute(d) || root === null) return false;
420	      const real = realOrNull(d);
421	      return real !== null && (broad || !isInside(root, real));
422	    })
423	    .join(path.delimiter);
424	  return env;
425	}
