445	interface FileState {
446	  text: string;
447	  /** Device, inode, size, mtime and ctime (ns). ctime is included because an edit can restore size and mtime but not it. */
448	  stamp: string;
449	  /** The stamp alone proves "unchanged" (see STAT_SETTLE_MS); otherwise the next check compares content. */
450	  settled: boolean;
451	}
452	
453	function stampOf(st: fs.BigIntStats, readAtMs: number): Pick<FileState, "stamp" | "settled"> {
454	  const newest = st.mtimeNs > st.ctimeNs ? st.mtimeNs : st.ctimeNs;
455	  return {
456	    stamp: `${st.dev}:${st.ino}:${st.size}:${st.mtimeNs}:${st.ctimeNs}`,
457	    settled: BigInt(readAtMs) * 1_000_000n - newest >= BigInt(STAT_SETTLE_MS) * 1_000_000n,
458	  };
459	}
