671	  private readiness(now: number): { ready: boolean; detail: string; at: number | null } {
672	    if (this.progressActive.size > 0) return { ready: false, detail: "work-done progress in flight", at: null };
673	    if (this.progressEnded > 0) {
674	      const at = this.lastProgressAt + this.t.quietMs;
675	      return now >= at ? { ready: true, detail: "its progress has ended", at } : { ready: false, detail: "its progress has just ended", at };
