750	    const where = /[\\/]/.test(this.serverCmd) ? "" : " on PATH";
751	    const notInstalled = `Language server not installed: ${this.serverCmd} was not found${where}.${this.installHint ? ` Install it with: ${this.installHint}` : ""}`;
