754	    try {
755	      // Its own process group (POSIX: a session of its own), so that stopping it stops what it started. Not unref'd:
756	      // the process is this client's to end.
757	      this.ownGroup = process.platform !== "win32";
758	      child = spawn(this.serverCmd, this.serverArgs, { cwd: this.rootPath, env, stdio: ["pipe", "pipe", "pipe"], detached: this.ownGroup });
