760	      throw this.fail("spawn_failed", `Language server '${this.serverCmd}' failed to start: it could not be executed (${err.code ?? err.message}).`);
761	    }
762	    this.child = child;
763	    try {
764	      child.stderr?.on("data", (chunk: Buffer) => {
765	        this.stderrRing = (chunk.length >= STDERR_RING_BYTES ? chunk : Buffer.concat([this.stderrRing, chunk])).subarray(-STDERR_RING_BYTES);
