767	
768	      // The process could not be executed (found, but its interpreter or a library is missing): no exit follows and
769	      // nothing will answer, so whoever waits is told now.
770	      child.on("error", (err: any) => {
771	        const how = this.lifecycle === "running" ? "stopped working" : "failed to start: it could not be executed";
