776	        this.failInFlight(failure);
777	      });
778	      child.on("spawn", () => {
779	        if (this.lifecycle === "starting") this.setLifecycle("initializing");
780	      });
781	
782	      let exited!: () => void;
783	      this.exited = new Promise<void>((resolve) => (exited = resolve));
