789	        child.on("exit", (code, signal) => {
790	          // Whatever the server started and left in its group goes with it, however it ended. Done at once: the group's
791	          // id is the pid just reaped.
792	          if (this.ownGroup && child.pid !== undefined) killGroup(child.pid, "SIGKILL");
793	          exited();
794	          const how = signal ? `killed by ${signal}` : `exit code ${code}`;
795	          const message = this.lifecycle === "running" ? `Language server '${this.serverCmd}' crashed (${how}).` : `Language server '${this.serverCmd}' failed to start: ${how}.`;
