797	          this.initialized = false;
798	          // Its last words are still in the pipe: wait for the streams to close, but not for long.
799	          let done = false;
800	          const finish = () => {
801	            if (done) return;
802	            done = true;
803	            clearTimeout(timer);
804	            // A process that outlived the server (outside its group) may hold the pipes open: they are not waited for.
805	            for (const stream of [child.stdin, child.stdout, child.stderr]) stream?.destroy();
806	            if (this.failure) this.failure.stderrTail = this.stderrTail();
807	            this.failInFlight(this.notRunning());
808	            resolve();
809	          };
810	          const timer = setTimeout(finish, STDERR_DRAIN_MS);
811	          child.once("close", finish);
812	        });
813	      });
814	      child.stdin?.on("error", () => {
815	        this.initialized = false;
816	      });
817	
818	      child.stdout?.on("data", (data: Buffer) => {
819	        this.handleData(data);
820	      });
