822	      const rootUri = pathToFileURL(this.rootPath).href;
823	
824	      // 1. Initialize
825	      const initRes = await this.sendRequest("initialize", {
826	        processId: process.pid,
827	        rootUri,
828	        capabilities: {
829	          textDocument: {
830	            hover: { contentFormat: ["markdown", "plaintext"] },
831	            definition: { dynamicRegistration: true },
832	            // Ask servers to attach document versions so delayed results for pre-edit content can be rejected.
833	            publishDiagnostics: { relatedInformation: true, versionSupport: true },
834	            synchronization: { didSave: true },
835	            // Pull diagnostics, except from a staged server: its lists come from several analyses and arrive by publish;
836	            // a pull would return one of them.
837	            ...(this.awaitProgress ? {} : { diagnostic: { dynamicRegistration: false, relatedDocumentSupport: false } }),
838	          },
839	          ...(this.awaitProgress ? {} : { workspace: { diagnostics: { refreshSupport: true } } }),
840	          // Declared so that servers which report progress (rust-analyzer) send $/progress, which diagnostics wait on.
841	          window: { workDoneProgress: true },
842	        },
843	      }, this.t.startMs);
844	
845	      if ((this.lifecycle as string) === "stopped") throw this.notRunning(); // stopped while the answer was on its way
846	      if (!initRes) throw new Error("it answered initialize with no result");
847	      const sync = initRes.capabilities?.textDocumentSync;
848	      if (typeof sync === "object" && sync?.save) {
849	        this.saveOptions = typeof sync.save === "object" ? sync.save : {};
850	      }
851	      const provider = initRes.capabilities?.diagnosticProvider;
852	      if (!this.awaitProgress && provider && typeof provider === "object") {
853	        this.diagnosticProvider = {
854	          ...(typeof provider.identifier === "string" ? { identifier: provider.identifier } : {}),
855	          interFileDependencies: provider.interFileDependencies === true,
856	          workspaceDiagnostics: provider.workspaceDiagnostics === true,
857	        };
858	      }
859	
860	      // 2. Initialized notification
861	      this.sendNotification("initialized", {});
862	      this.initializedAt = this.busySince = Date.now();
863	      this.setLifecycle("running");
864	    } catch (err: any) {
