export interface LspTimings {
  startMs: number;
  queryMs: number;
  coldStartMs: number;
  quietMs: number;
  editSettleMs: number;
  retryMs: number;
  startRecheckMs: number;
  restartBackoffMs: number;
  maxRestarts: number;
  shutdownReplyMs: number;
  exitGraceMs: number;
  termGraceMs: number;
  killGraceMs: number;
