461	/**
462	 * The regular file at `real` (a path already resolved through symlinks), or null. The descriptor refuses a symlink put in
463	 * the last component since the path was resolved, and does not block on a FIFO; the stamp is of the file actually read.
464	 * A file over `maxBytes` is not read: its size comes back instead (also when it grew past the limit between the stat and
465	 * the read, in which case what was read is dropped).
466	 */
467	function readRegularFile(real: string, maxBytes: number): FileState | { tooLarge: number } | null {
468	  let fd: number | undefined;
469	  try {
470	    const readAtMs = Date.now();
471	    fd = fs.openSync(real, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0) | (fs.constants.O_NONBLOCK ?? 0));
472	    const st = fs.fstatSync(fd, { bigint: true });
473	    if (!st.isFile()) return null;
474	    if (st.size > BigInt(maxBytes)) return { tooLarge: Number(st.size) };
475	    const text = fs.readFileSync(fd, "utf-8");
476	    const bytes = text.length > maxBytes ? text.length : Buffer.byteLength(text, "utf-8");
477	    if (bytes > maxBytes) return { tooLarge: bytes };
478	    return { text, ...stampOf(st, readAtMs) };
479	  } catch {
480	    return null;
481	  } finally {
482	    if (fd !== undefined) fs.closeSync(fd);
483	  }
484	}
