906	      const headerEnd = this.buffer.indexOf("\r\n\r\n");
907	      if (headerEnd === -1 ? this.buffer.length > LSP_MAX_HEADER_BYTES : headerEnd > LSP_MAX_HEADER_BYTES) return this.dropOversized(`more than ${LSP_MAX_HEADER_BYTES} bytes that are not a message header`);
908	      if (headerEnd === -1) break;
909	
910	      const header = this.buffer.subarray(0, headerEnd).toString("latin1");
911	      const match = header.match(/Content-Length:\s*(\d+)/i);
912	      if (!match) {
913	        this.buffer = this.buffer.subarray(headerEnd + 4);
914	        continue;
915	      }
