919	      if (contentLength > this.limits.messageBytes) return this.dropOversized(`a message of ${contentLength} bytes, over the ${this.limits.messageBytes}-byte limit`);
920	      const bodyStart = headerEnd + 4;
921	
922	      if (this.buffer.length < bodyStart + contentLength) {
