202	    target[name] = Object.assign(function (this: unknown, ...args: unknown[]) {
203	      calls.push([name, String(args[0])]);
204	      return original.apply(this, args);
205	    }, original);
206	  }
207	  syncBuiltinESMExports();
208	  try {
209	    return { result: await run(), calls };
210	  } finally {
