131	function hoverFromText(_uri, word) {
132	  return { contents: JSON.stringify({ word, docs: Object.fromEntries([...docs].map(([u, text]) => [base(u), text])) }) };
133	}
134	
135	function definitionFromText(_uri, word) {
136	  for (const [uri, text] of docs) {
137	    const lines = text.split("\n");
138	    const line = lines.findIndex((l) => word !== "" && l.includes(`def ${word}`));
139	    if (line < 0) continue;
140	    const character = lines[line].indexOf(`def ${word}`) + 4;
141	    return { uri, range: { start: { line, character }, end: { line, character: character + word.length } } };
142	  }
143	  return null;
144	}
145	
146	let pulls = 0;
147	function diagnosticAnswer(m) {
148	  const uri = m.params.textDocument.uri;
149	  if (S.diagnostic !== "fromText") return S.diagnostic?.[Math.min(pulls++, S.diagnostic.length - 1)] ?? { result: null };
150	  const message = `${base(uri)} with ${[...docs].map(([u, text]) => `${base(u)}=${text}`).sort().join(" ")}`;
151	  if (m.params.previousResultId === message) return { result: { kind: "unchanged", resultId: message } };
152	  const range = { start: { line: 0, character: 0 }, end: { line: 0, character: 1 } };
153	  return { result: { kind: "full", resultId: message, items: [{ range, severity: 1, message, source: "fake" }] } };
154	}
155	
156	function handle(m) {
157	  if (m.method === undefined) {
158	    log({ event: "reply", to: sent.get(m.id), id: m.id, ...("result" in m ? { result: m.result } : {}), ...(m.error ? { error: m.error } : {}) });
159	    return;
160	  }
161	  const doc = m.params?.textDocument;
162	  if (m.method === "initialize") rootUri = m.params.rootUri;
163	  if (m.method === S.loadedOn) loaded = true;
164	  if (m.method === "textDocument/didOpen") docs.set(doc.uri, doc.text);
165	  if (m.method === "textDocument/didChange") docs.set(doc.uri, m.params.contentChanges.at(-1).text);
166	  if (m.method === "textDocument/didClose") docs.delete(doc.uri);
167	  log({ event: "recv", method: m.method, ...(m.id !== undefined ? { id: m.id } : {}), params: m.params, docs: Object.fromEntries([...docs].map(([u, text]) => [u, elide("text", text)])) });
168	
169	  const ctx = { uri: doc?.uri, version: doc?.version };
170	  run(m.method, ctx);
171	  if (doc?.uri) run(`${m.method}#${base(doc.uri)}`, ctx);
172	
173	  if (m.method === "exit") {
174	    if (!S.ignoreShutdown) process.exit(0);
175	    return;
176	  }
177	  if (m.id === undefined) return;
178	  if (m.method === "initialize") {
179	    if (S.initialize !== "never") send({ id: m.id, result: S.initialize ?? { capabilities: {} } });
180	  } else if (m.method === "shutdown") {
181	    if (!S.ignoreShutdown) send({ id: m.id, result: null });
182	  } else if (m.method === "textDocument/hover" || m.method === "textDocument/definition") {
183	    const result = m.method === "textDocument/hover" ? answer(S.hover, m, hoverFromText) : answer(S.definition, m, definitionFromText);
184	    if (result !== "never") send({ id: m.id, result });
185	  }
186	  else if (m.method === "textDocument/diagnostic") {
187	    const scripted = diagnosticAnswer(m);
188	    if (scripted === "never") return;
189	    const reply = scripted.error ? { error: scripted.error } : { result: fill(scripted.result, ctx) };
190	    log({ event: "answer", to: m.method, ...reply });
191	    send({ id: m.id, ...reply });
192	  }
193	  else send({ id: m.id, result: null });
194	}
195	
196	if (S.ignoreStdinEnd) setTimeout(() => process.exit(0), 60000);
197	else process.stdin.on("end", () => process.exit(0));
198	process.stdin.on("data", (chunk) => {
199	  buf = Buffer.concat([buf, chunk]);
200	  for (;;) {
201	    const headerEnd = buf.indexOf("\r\n\r\n");
202	    if (headerEnd < 0) return;
203	    const length = Number(/Content-Length:\s*(\d+)/i.exec(buf.subarray(0, headerEnd).toString())[1]);
204	    if (buf.length < headerEnd + 4 + length) return;
205	    const body = buf.subarray(headerEnd + 4, headerEnd + 4 + length).toString();
206	    buf = buf.subarray(headerEnd + 4 + length);
207	    handle(JSON.parse(body));
208	  }
209	});
