528	    for (const name of names.slice(0, MAX_OPEN_DOCUMENTS)) assert.deepEqual(await message(name), [`first ${name}`]);
529	    assert.deepEqual(await message("f0.ts"), ["first f0.ts"]); // queried again: f1.ts is now the least recently queried
530	    assert.deepEqual(await closed(), [], "at the bound nothing is closed");
531	    assert.equal(Object.keys((await s.log()).at(-1)!.docs!).length, MAX_OPEN_DOCUMENTS);
532	
533	    assert.deepEqual(await message(names[MAX_OPEN_DOCUMENTS]), [`first ${names[MAX_OPEN_DOCUMENTS]}`]);
534	    assert.deepEqual(await closed(), [s.uri("f1.ts")]);
535	    const client = (await s.client()) as any;
536	    assert.equal(client.documents.size, MAX_OPEN_DOCUMENTS);
537	    assert.equal(client.opened.size, MAX_OPEN_DOCUMENTS);
538	    assert.equal(client.opened.has(s.uri("f1.ts")), false, "its text and its diagnostics went with it");
539	    const held = Object.keys((await s.log()).at(-1)!.docs!);
540	    assert.equal(held.length, MAX_OPEN_DOCUMENTS, "the server holds no more than the client");
541	    assert.equal(held.includes(s.uri("f1.ts")), false);
542	
543	    // The closed file changes on disk, then is asked about again: opened anew, answered from its new text, and the next
544	    // least recently queried document (f2.ts) makes room for it.
545	    fs.writeFileSync(path.join(s.ws, "f1.ts"), "second f1.ts");
546	    assert.deepEqual(await message("f1.ts"), ["second f1.ts"]);
547	    assert.deepEqual((await s.received("textDocument/didOpen")).filter((e) => e.params.textDocument.uri === s.uri("f1.ts")).map((e) => e.params.textDocument.text), ["first f1.ts", "second f1.ts"]);
