142	function writeFixture(files: Record<string, string>): string {
143	  const dir = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-lsp-real-")));
144	  for (const [name, text] of Object.entries(files)) {
145	    fs.mkdirSync(path.dirname(path.join(dir, name)), { recursive: true });
146	    fs.writeFileSync(path.join(dir, name), text);
147	  }
148	  return dir;
