167	for (const c of CASES) {
168	  // An unvalidated case still runs and reports; it fails the run only when NEXUS_LSP_REQUIRE names it.
169	  const todo = c.unvalidated && !required(c.id) ? c.unvalidated : false;
170	  test(`real ${c.label}: a deliberate error is reported, a clean file is a real empty report`, { timeout: c.timeoutMs * 2 + 30_000, todo }, async (t) => {
171	    const dir = writeFixture(c.files);
172	    const reason = unavailableReason(c, dir);
173	    if (reason) {
174	      if (required(c.id)) assert.fail(`NEXUS_LSP_REQUIRE names ${c.id} but ${reason}`);
175	      t.skip(`${reason}; install it to run this case (CI sets NEXUS_LSP_REQUIRE to make this a failure)`);
176	      return;
177	    }
178	    // Default server table (no `servers` override) and no gate: a trusted, unsandboxed workspace.
179	    const mgr = new LspBridgeManager(dir, { gate: () => null });
180	    try {
181	      const bad = await mgr.diagnostics(c.bad, c.timeoutMs);
182	      assert.equal(bad.status, "ok", `bad file: ${JSON.stringify(bad)}`);
183	      if (bad.status === "ok") {
184	        const errors = bad.diagnostics.filter((d) => d.severity === "error");
185	        assert.ok(errors.length >= 1, `expected an error diagnostic, got ${JSON.stringify(bad.diagnostics)}`);
186	        assert.ok(errors.some((d) => c.message.test(d.message)), `no error matched ${c.message}: ${JSON.stringify(errors.map((d) => d.message))}`);
187	      }
188	
189	      const clean = await mgr.diagnostics(c.clean, c.timeoutMs);
190	      assert.equal(clean.status, "ok", `clean file must be a published report, not unavailable: ${JSON.stringify(clean)}`);
191	      if (clean.status === "ok") assert.deepEqual(clean.diagnostics.filter((d) => d.severity === "error"), []);
192	    } finally {
193	      await mgr.shutdownAll();
194	    }
