196	    // The contrast: no server for the file's content is "unavailable", never an empty ok report.
197	    const broken = new LspBridgeManager(dir, { servers: { [path.extname(c.clean)]: { cmd: "nexus-no-such-language-server", languageId: c.id } } });
198	    try {
199	      const res = await broken.diagnostics(c.clean, 1000);
200	      assert.equal(res.status, "unavailable");
