251	      const afterCrash = await mgr.diagnostics(c.bad, 5000);
252	      assert.ok(afterCrash.status === "unavailable" || afterCrash.diagnostics.some((d) => d.severity === "error" && c.message.test(d.message)),
253	        `after a server crash, stale clean diagnostics must not be returned: ${JSON.stringify(afterCrash)}`);
254	    } finally {
