258	    // A fresh manager can recover the same workspace without inheriting the crashed process or its diagnostics.
259	    const recovered = new LspBridgeManager(dir, { gate: () => null });
260	    try {
261	      const result = await recovered.diagnostics(c.bad, c.timeoutMs);
262	      assert.equal(result.status, "ok", `recovery after server crash: ${JSON.stringify(result)}`);
263	      if (result.status === "ok") assert.ok(result.diagnostics.some((d) => d.severity === "error" && c.message.test(d.message)));
264	    } finally {
265	      await recovered.shutdownAll();
266	    }
