298	// Navigation (hover and definition) against the same real servers: a function defined in one file and called in another.
299	// A server answers these only once it has analysed the project, so the call is retried until a deadline; a server that never
300	// answers is a failure, and an answer is checked for what it names, not merely for existing.
301	interface NavCase {
302	  id: string;
303	  files: Record<string, string>;
304	  /** The call site (1-based line and character, as the product's lsp_hover/lsp_definition take them, on the callee's name) and the file that defines it. */
305	  at: { file: string; line: number; character: number };
306	  definedIn: string;
