310	const NAV: NavCase[] = [
311	  {
312	    id: "typescript",
313	    files: {
314	      "tsconfig.json": JSON.stringify({ compilerOptions: { strict: true, noEmit: true, target: "es2022", module: "esnext", moduleResolution: "bundler" }, include: ["*.ts"] }),
315	      "lib.ts": "export function greet(name: string): string {\n  return name;\n}\n",
316	      "service.ts": 'export { greet } from "./lib";\n',
317	      "use.ts": 'import { greet } from "./service";\nexport const msg: string = greet("a");\n',
318	    },
319	    at: { file: "use.ts", line: 2, character: 30 },
320	    definedIn: "lib.ts",
321	    hoverMentions: /greet/,
322	  },
323	  {
324	    id: "python",
325	    files: {
326	      "pyrightconfig.json": JSON.stringify({ typeCheckingMode: "basic" }),
327	      "lib.py": "def greet(name: str) -> str:\n    return name\n",
328	      "service.py": "from lib import greet\n",
329	      "use.py": 'from service import greet\n\nmsg: str = greet("a")\n',
330	    },
331	    at: { file: "use.py", line: 3, character: 13 },
332	    definedIn: "lib.py",
333	    hoverMentions: /greet/,
334	  },
335	  {
336	    id: "rust",
337	    files: {
338	      "Cargo.toml": '[package]\nname = "lspnav"\nversion = "0.0.0"\nedition = "2021"\n',
339	      "src/util.rs": "pub fn greet(name: &str) -> String {\n    name.to_string()\n}\n",
340	      "src/service.rs": "pub use crate::util::greet;\n",
341	      "src/main.rs": 'mod service;\nmod util;\nfn main() {\n    let _ = service::greet("a");\n}\n',
342	    },
343	    at: { file: "src/main.rs", line: 4, character: 25 },
344	    definedIn: "src/util.rs",
345	    hoverMentions: /greet/,
346	  },
347	  {
348	    id: "go",
349	    files: {
350	      "go.mod": "module lspnav\n\ngo 1.21\n",
351	      "lib.go": "package main\n\nfunc greet(name string) string {\n\treturn name\n}\n",
352	      "service.go": "package main\n\nfunc welcome(name string) string {\n\treturn greet(name)\n}\n",
353	      "main.go": 'package main\n\nfunc main() {\n\t_ = welcome("a")\n}\n',
354	    },
355	    at: { file: "main.go", line: 4, character: 7 },
356	    definedIn: "service.go",
357	    hoverMentions: /welcome/,
358	  },
