372	    try {
373	      const deadline = Date.now() + c.timeoutMs;
374	      let hover: Awaited<ReturnType<typeof mgr.hover>> = { found: false };
375	      let def: Awaited<ReturnType<typeof mgr.definition>> = { found: false };
376	      // A server may answer early from what it has loaded so far (tsserver names the import itself until the imported file is
377	      // loaded), so an answer counts once it points where the definition is; the last answer is what the assertions report.
378	      // Since LS-1 slice S5 a target is {file, line, column, ...}: `file` relative to the workspace, "/"-separated.
379	      const pointsAtDefinition = (d: typeof def) => (d.locations ?? []).some((l) => l.file === n.definedIn || l.file?.endsWith(`/${n.definedIn}`));
380	      while (Date.now() < deadline && !(hover.found && pointsAtDefinition(def))) {
