388	      assert.ok(pointsAtDefinition(def), `definition should point into ${n.definedIn}, got ${JSON.stringify(def.locations)}`);
389	      assert.ok((def.locations ?? []).every((l) => l.external !== true && l.line >= 1 && l.column >= 1), `targets inside the workspace, 1-based: ${JSON.stringify(def.locations)}`);
390	    } finally {
391	      await mgr.shutdownAll();
392	    }
393	  });
394	}
