    const { result, calls } = await countingFs(() => s.tool("lsp_definition", { path: "a.ts", line: 2, character: 18 }));
    assert.deepEqual(JSON.parse(result.output), [
      { file: "sub/c.ts", line: 2, column: 10, endLine: 2, endColumn: 16 },
