    assert.deepEqual(roots(t.ws, ["web/src/deep/x.ts", "web/pkg/lib/y.tsx", "tools/z.js", "loose/w.ts", "top.jsx"]), {
      "web/src/deep/x.ts": "web",
      "web/pkg/lib/y.tsx": "web/pkg",
